import { requireVendorSession } from "../../../../../lib/vendor-session";import { vendorBoxNowLabel } from "../../../../../lib/boxnow-shipping-runtime";
export async function GET(request:Request){try{const p=await requireVendorSession();const id=new URL(request.url).searchParams.get('shipmentId')?.trim()??'';if(!id)throw new Error('shipmentId is required');const pdf=await vendorBoxNowLabel(p,id);return new Response(pdf,{headers:{'content-type':'application/pdf','content-disposition':`inline; filename="boxnow-${id}.pdf"`,'cache-control':'private, no-store'}})}catch(e){return Response.json({error:e instanceof Error?e.message:'boxnow_label_failed'},{status:400})}}
